let topicCategory='all',topicSentiment='all',topicRoom='all',showCompletedIssues=false;
const aspectCompleted=a=>!!(workflowState(a.r.id+'|'+a.category).fixed||workflowState(a.r.id+'|'+a.category).notReal);
function renderTodayOverview(){
 const host=document.querySelector('#todayOverview');if(!host)return;
 const reviews=nightReport.reviews.filter(r=>(selected==='all'||r.property===selected)&&(platform==='all'||r.platform===platform));
 const replies=reviews.filter(r=>r.replyStatus==='unanswered'&&!workflowState(r.id).answered).length;
 const issues=reviewAspectEvidence.flatMap(i=>{const r=reviews.find(r=>r.id===i.reviewId);return r?i.aspects.filter(a=>a.sentiment==='bad').map(a=>({...a,r})):[];}).filter(a=>!aspectCompleted(a)).length;
 host.innerHTML=`<div class="eyebrow">DIT OVERBLIK</div><h2>Hvad skal vi gøre?</h2><div class="today-actions"><a href="#nightReport"><strong>${replies}</strong><span>Anmeldelser mangler svar</span></a><a href="#reviewTopics"><strong>${teamRole?issues:'—'}</strong><span>${teamRole?'Punkter mangler handling':'Log ind for fælles opgavestatus'}</span></a></div><p class="footnote">Tallene gælder det gennemgåede udsnit og dit valgte sted. Log ind for at se teamets afsluttede opgaver.</p>`;
}
function renderReviewTopics(){
 const host=document.querySelector('#reviewTopics');if(!host)return;
 const e=escapeHTML;
 const rows=reviewAspectEvidence.flatMap(item=>{
  const r=nightReport.reviews.find(r=>r.id===item.reviewId);if(!r)return [];
  const listing=airbnbListings.find(l=>l.url===r.url&&l.property===r.property);
  const room=item.roomNumber?'Værelse '+item.roomNumber:listing?'Type: '+listing.title:r.property==='jylkat'?'Bar / restaurant':'Værelse ikke oplyst';
  return item.aspects.map(a=>({...a,r,room}));
 }).filter(a=>(selected==='all'||a.r.property===selected)&&(platform==='all'||a.r.platform===platform));
 const rooms=[...new Set(rows.map(a=>a.room))].sort();if(!rooms.includes(topicRoom))topicRoom='all';
 const subset=rows.filter(a=>(topicRoom==='all'||a.room===topicRoom)&&(topicSentiment==='all'||a.sentiment===topicSentiment));
 const categories=Object.entries(reviewCategories).map(([id,label])=>({id,label,good:new Set(subset.filter(a=>a.category===id&&a.sentiment==='good').map(a=>a.r.id)).size,bad:new Set(subset.filter(a=>a.category===id&&a.sentiment==='bad').map(a=>a.r.id)).size})).sort((a,b)=>b.bad-a.bad||b.good-a.good);
 const details=subset.filter(a=>(topicCategory==='all'||a.category===topicCategory)&&(a.sentiment!=='bad'||showCompletedIssues||!aspectCompleted(a)));
 const completedCount=subset.filter(a=>a.sentiment==='bad'&&aspectCompleted(a)).length;
 const unique=new Set(rows.map(a=>a.r.id)).size;
 host.innerHTML=`<div class="section-heading"><div><div class="eyebrow">HVOR SKAL VI SÆTTE IND?</div><h2>Ros og kritik efter emne</h2></div><span class="tag">${unique} ${unique===1?'gennemgået anmeldelse':'gennemgåede anmeldelser'}</span></div><div class="topic-filters"><label>Vis<select id="topicSentiment"><option value="all">Ros og kritik</option><option value="bad" ${topicSentiment==='bad'?'selected':''}>Kun kritik</option><option value="good" ${topicSentiment==='good'?'selected':''}>Kun ros</option></select></label><label>Værelse / værelsestype<select id="topicRoom"><option value="all">Alle / ikke oplyst</option>${rooms.map(r=>`<option ${topicRoom===r?'selected':''} value="${e(r)}">${e(r)}</option>`).join('')}</select></label></div><div class="topic-grid"><button type="button" data-topic="all" aria-pressed="${topicCategory==='all'}"><strong>Alle emner</strong><span>Se hele udsnittet</span></button>${categories.map(c=>`<button type="button" data-topic="${c.id}" aria-pressed="${topicCategory===c.id}" ${c.bad+c.good===0?'disabled':''}><strong>${e(c.label)}</strong><span><b class="topic-bad">${c.bad} kritik</b> · <b class="topic-good">${c.good} ros</b></span></button>`).join('')}</div><label class="workflow-check"><input id="showCompletedIssues" type="checkbox" ${showCompletedIssues?'checked':''}>Vis afsluttede punkter (${completedCount})</label><h3>${topicCategory==='all'?'Konkrete observationer':e(reviewCategories[topicCategory])}</h3><p class="footnote">Værelsesnummer vises kun, hvis gæsten har oplyst det. Airbnb-opslag identificerer en værelsestype, ikke et bestemt fysisk værelse. “Værelse ikke oplyst” skal afklares, før en rengøringsklage knyttes til et værelse. Gæsternes beskrivelser skal undersøges på stedet.</p>${teamRole?'':'<p class="workflow-storage">Log ind øverst for at se kollegernes markeringer og skrive noter.</p>'}<div class="praise-criticism"><section class="praise-column"><div class="mood-heading">${details.some(a=>a.sentiment==='good')?'<img class="mood-pind mood-pind--happy" src="assets/pind-fejrer.png" alt="Pind smiler og hopper glad ved ros">':''}<h3>Ros <span>${new Set(details.filter(a=>a.sentiment==='good').map(a=>a.r.id)).size}</span></h3></div>${renderAspectCards(details.filter(a=>a.sentiment==='good'))}</section><section class="criticism-column"><div class="mood-heading">${details.some(a=>a.sentiment==='bad')?'<span class="mood-tears"><img class="mood-pind mood-pind--sad" src="assets/pind-ked-af-det.png" alt="Pind er ked af det med tårer, der drypper ned ved kritik"><i class="pind-tear pind-tear--left" aria-hidden="true"></i><i class="pind-tear pind-tear--right" aria-hidden="true"></i></span>':''}<h3>Kritik <span>${new Set(details.filter(a=>a.sentiment==='bad').map(a=>a.r.id)).size}</span></h3></div>${renderAspectCards(details.filter(a=>a.sentiment==='bad'))}</section></div>`;
 bindWorkflowControls(host);
 host.querySelector('#showCompletedIssues').addEventListener('change',ev=>{showCompletedIssues=ev.target.checked;renderReviewTopics();});
 host.querySelectorAll('[data-show-more]').forEach(b=>b.addEventListener('click',()=>{const list=b.closest('.aspect-list');const open=b.dataset.open==='1';list.querySelectorAll('.aspect-card').forEach((c,i)=>{if(i>=3)c.hidden=open;});b.dataset.open=open?'':'1';b.textContent=open?`Vis alle ${b.dataset.total} anmeldelser`:'Vis færre';if(open)list.scrollIntoView({block:'start'});}));
 host.querySelectorAll('[data-topic]').forEach(b=>b.addEventListener('click',()=>{topicCategory=b.dataset.topic;renderReviewTopics();host.querySelector(`[data-topic="${topicCategory}"]`).focus();}));
 host.querySelector('#topicSentiment').addEventListener('change',event=>{topicSentiment=event.target.value;renderReviewTopics();});
 host.querySelector('#topicRoom').addEventListener('change',event=>{topicRoom=event.target.value;renderReviewTopics();});
}

const teamNews={property:'summer',date:'2026-10-08',expiresOn:'2026-10-08',title:'Mega godt gået, team!',text:'Gamle Bryggeri er blevet Superhost på Airbnb! Jannie fortæller, at I har opfyldt kravene i perioden og løftet ratingen til 4,8. Tak for jeres arbejde med at give gæsterne en fantastisk oplevelse.',source:'Nyhed oplyst af Jannie 8. oktober. Periodens rating er ikke bekræftet som opslagets samlede bedømmelse.'};
function renderTeamCelebration(){
 const box=document.querySelector('#celebration');if(!box)return;
 const today=new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Copenhagen'});
 const fresh=nightReport.reviews.filter(r=>r.classification==='new_review'&&r.score/r.scale>=0.8&&r.publishedDate&&r.firstSeenAt?.slice(0,10)===today&&(selected==='all'||selected===r.property)&&(platform==='all'||platform===r.platform)&&!reviewAspectEvidence.find(a=>a.reviewId===r.id)?.aspects.some(a=>a.sentiment==='bad')).sort((a,b)=>b.publishedDate.localeCompare(a.publishedDate))[0];
 const news=today===teamNews.date&&(selected==='all'||selected===teamNews.property)&&(platform==='all'||platform==='Airbnb');
 box.hidden=!news&&!fresh;box.dataset.newsId=news?today+'|superhost':fresh?today+'|'+fresh.id:'';if(box.hidden)return;
 const e=escapeHTML;
 box.innerHTML=`<span class="celebration-spark" aria-hidden="true">🎆 ✨ 🎉</span><div><div class="eyebrow">DET SKAL VI FEJRE</div><h2>Mega godt gået, team!</h2>${news?`<p>${e(teamNews.text)}</p><small>${e(teamNews.source)}</small>`:`<p><strong>${e(properties.find(p=>p.id===fresh.property).name)} har fået ${fresh.score}/${fresh.scale}!</strong> ${e(fresh.summary||'Tak for jeres arbejde med gæsternes oplevelse.')}</p><a href="${e(fresh.url)}" target="_blank" rel="noopener noreferrer">Læs ${e(fresh.author)}s anmeldelse · ${e(fresh.publishedDate)}</a>`}</div>`;
}



